/// Deal status. Identifiers are code, not copy: use [DealStatusX.label] for UI text.
/// v1.6: Added watchingForDrops and changedAfterAccepted (10 total).
enum DealStatus {
  reachingOut,
  findingBestPrice,
  offerReceived,
  accepted,
  officialOfferReceived,
  paused,
  noResponse,
  noLongerListed,
  watchingForDrops,
  changedAfterAccepted,
}

extension DealStatusX on DealStatus {
  String get label => switch (this) {
        DealStatus.reachingOut => 'Reaching out',
        DealStatus.findingBestPrice => 'Finding your best price',
        DealStatus.offerReceived => 'Offer received',
        DealStatus.accepted => 'Accepted',
        DealStatus.officialOfferReceived => 'Official offer received',
        DealStatus.paused => 'Paused',
        DealStatus.noResponse => 'No response',
        DealStatus.noLongerListed => 'No longer listed',
        DealStatus.watchingForDrops => 'Watching for drops',
        DealStatus.changedAfterAccepted => 'Offer changed',
      };

  /// Filled progress segments (1–4). Paused/No longer listed keep the step the deal had reached; null = use last known.
  int? get progressStep => switch (this) {
        DealStatus.reachingOut => 1,
        DealStatus.findingBestPrice => 2,
        DealStatus.offerReceived => 3,
        DealStatus.accepted => 4,
        DealStatus.officialOfferReceived => 4,
        DealStatus.paused => null,
        DealStatus.noResponse => 1,
        DealStatus.noLongerListed => null,
        DealStatus.watchingForDrops => 2,
        DealStatus.changedAfterAccepted => 4,
      };

  bool get isEnded => this == DealStatus.noResponse || this == DealStatus.noLongerListed;
  bool get dealerRevealed => this == DealStatus.officialOfferReceived;
  bool get canWithdraw => this == DealStatus.accepted;
  bool get hasChangedOffer => this == DealStatus.changedAfterAccepted;
}

